head.script:
scwin.onpageload = function() { 

};
//input 동적 생성 이벤트
scwin.btn_set_onclick = function (e) {

    //1. 필요한 변수 선언
    //2. 중복되지 않는 ID 생성을 위한 스크립트
    //3. input 생성 $p.dynamicCreate() 
    //4. 생성된 input의 더 필요한 속성 있을경우 기재

    var _comp;
		var compXml = [];
        var strID;
        var objDate;
         objDate = new Date();
         strID = "ipt_ex_" + objDate.getDate() + "_" + objDate.getTime();


		compXml.push('<xf:input xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms" style="width: 144px;height: 31px; margin-right:10px;">');
        compXml.push('</xf:input>');

        //ui_ipt1.getPluginName(); 
		_comp = $p.dynamicCreate(strID, "input", compXml.join(""), grp1);

        _comp.setPlaceholder("입력하세요");
};

//버튼 동적 생성 이벤트
scwin.btn_triggerDy_onclick = function (e) {
    //1. 필요한 변수 선언
    //2. 중복되지 않는 ID 생성을 위한 스크립트
    //3. 버튼(trigger) 생성 $p.dynamicCreate() 
    //4. 생성된 trigger의 더 필요한 속성 있을경우 기재
    var _comp;
    var strID;
    var objDate;

    objDate = new Date();
    strID = "btn_ex_" + objDate.getDate() + "_" + objDate.getTime();

    _comp = $p.dynamicCreate(
        strID,
        "trigger", //생성할 컴포넌트의 pluginName
        {
              style: ""
            , className: "btn_cm pt"
        },
        grp1  //추가될 부모 컴포넌트 객체 ID
    );

     _comp.setValue("버튼");


};
